private List<Pair<List<Pair<Integer,Integer>>,E>> computeGlobalSeparatorList() {
    // Compute the separator list for every edge in the graph
    List<Pair<List<Pair<Integer,Integer>>,E>> separatorList = new ArrayList<>();
    for (E edge : graph.edgeSet()) {
        // Compute the minimal separators for the edge
        List<Pair<Integer,Integer>> separators = computeMinimalSeparators(edge);
        // Add the separators to the list
        separatorList.add(new Pair<>(separators, edge));
    }
    return separatorList;
}

private List<Pair<Integer,Integer>> computeMinimalSeparators(E edge) {
    // Compute the neighborhood of the edge
    Set<E> neighborhood = graph.neighborhood(edge);
    // Compute the separator list for the neighborhood
    List<Pair<List<Pair<Integer,Integer>>,E>> separatorList = computeGlobalSeparatorList(neighborhood);
    // Compute the minimal separators for the edge
    List<Pair<Integer,Integer>> separators = new ArrayList<>();
    for (Pair<List<Pair<Integer,Integer>>,E> pair : separatorList) {
        if (pair.getSecond().equals(edge)) {
            separators.addAll(pair.getFirst());
        }
    }
    return separators;
}

